  await select(priority, 'High');
  assert.deepEqual(titles(), ['Low open', 'High open']);
  const checkbox = rows()[0].querySelector('input');
  checkbox.checked = true;
  await checkbox.fire('change');
  assert.deepEqual(titles(), ['High open']);
