/bin/bash -lc "node --input-type=module <<'NODE'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const temporary = await mkdtemp(join(tmpdir(), 'workboard-health-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '18922', DB_PATH: join(temporary, 'health.sqlite') }, detached: true, stdio: 'ignore' });
try {
  let response;
  for (let attempt = 0; attempt < 100; attempt++) {
    try { response = await fetch('http://127.0.0.1:18922/health'); break; }
    catch { await new Promise(resolve => setTimeout(resolve, 50)); }
  }
  assert.equal(response?.status, 200);
  assert.deepEqual(await response.json(), { status: 'ok' });
  console.log('npm start: health HTTP 200, {\"status\":\"ok\"}');
} finally {
  const exited = new Promise(resolve => child.once('exit', resolve));
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(temporary, { recursive: true, force: true });
}
NODE
"

